function textWidth(str, scale = 1) {
  return Math.max(0, str.length * 6 * scale - scale);
}

function drawText(str, x, y, color = '#fff', scale = 1, align = 'left') {
  str = String(str).toUpperCase();
  let px = x;
  if (align === 'center') px -= textWidth(str, scale) / 2;
  if (align === 'right') px -= textWidth(str, scale);
  ctx.fillStyle = color;
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    const glyph = FONT[ch] || FONT['?'];
    for (let row = 0; row < 7; row++) {
      for (let col = 0; col < 5; col++) {
        if (glyph[row][col] === '1') {
          ctx.fillRect(Math.floor(px + col * scale), Math.floor(y + row * scale), scale, scale);
        }
      }
    }
    px += 6 * scale;
  }
}

