const formationSlots = [];
(function buildSlots() {
  // Boss row: 4
  const bossX = [88, 104, 120, 136];
  for (let i = 0; i < 4; i++) {
    formationSlots.push({ type: 'boss', baseX: bossX[i], baseY: 52 });
  }
  // Goei rows: 2 x 8
  for (let row = 0; row < 2; row++) {
    for (let i = 0; i < 8; i++) {
      formationSlots.push({ type: 'goei', baseX: 56 + i * 16, baseY: 66 + row * 14 });
    }
  }
  // Zako rows: 2 x 10
  for (let row = 0; row < 2; row++) {
    for (let i = 0; i < 10; i++) {
      formationSlots.push({ type: 'zako', baseX: 40 + i * 16, baseY: 94 + row * 14 });
    }
  }
})();

function slotPos(slot) {
  const sway = Math.sin(game.time * 1.4) * (game.formationComplete ? 1.2 : 3.5);
  let x = slot.baseX + sway;
  if (game.formationComplete) {
    const breath = 1 + Math.sin(game.time * 2.1) * 0.055;
    x = 112 + (slot.baseX - 112) * breath + sway * 0.25;
  }
  return { x, y: slot.baseY };
}

function resetPlayerForStage() {
  game.player.x = 112;
  game.player.ships = 1;
  game.player.alive = true;
  game.player.respawning = false;
  game.player.respawnTimer = 0;
  game.player.capture = null;
